// Receives { soc, batteryVoltage, batterySystemStateNum, insideC, outsideC }
// from the simulator's /api/sensors endpoint and emits one message per
// sensor with a `path` field that matches the dispatch logic in the
// 'Daten sammeln' function (which keys off substring matches in msg.path).
var s = msg.payload || {};
if (typeof s !== 'object') {
    node.warn('expected object payload from /api/sensors, got ' + typeof s);
    return null;
}

if (typeof s.soc === 'number') {
    node.send({ path: 'Battery SOC', payload: s.soc });
}
if (typeof s.batterySystemStateNum === 'number') {
    node.send({ path: 'Battery State', payload: s.batterySystemStateNum });
}
if (typeof s.batteryVoltage === 'number') {
    node.send({ path: 'Battery Voltage', payload: s.batteryVoltage });
}
if (typeof s.insideC === 'number') {
    node.send({ path: 'Ruuvi Innen', payload: s.insideC });
}
if (typeof s.outsideC === 'number') {
    node.send({ path: 'Ruuvi Außen', payload: s.outsideC });
}
node.status({ fill: 'green', shape: 'dot', text: 'pumped ' + new Date().toISOString().slice(11,19) });
return null;
